SELECT 'MM-2024-1007',42.528827919130755,72.22223281860353,'talas','Талас','https://www.facebook.com/284851126287410/posts/1096236271815554','2024-жылдын октябрында жергиликтүү кеңештерге шайлоо алдындагы үгүт иштеринин жүрүшүндө биз Фейсбукта мындай билдирүүлөрдү жана комментарийлерди көрдүк, анда партиянын талапкерлеринин бири, жаш кыз, колдонуучулар тарабынан кемсинтилген жана веб-камерадагы студияда иштегени үчүн айыпталган.','Баалоо: Шайлоо өнөктүгү учурунда талапкердин веб-камера бизнесинде иштегени тууралуу гендердик кемсинтүүлөр жана айыптоолор менен Фейсбукта билдирүүлөрдү жана комментарийлерди таратуу этикалык нормаларды жана мыйзамдарды одоно бузуу болуп саналат. Бул жөн гана этикага жатпаган саясий өнөктүк эмес, талапкердин аброюн түшүрүүгө жана анын аброюна шек келтирүүгө багытталган жек көрүүчүлүк сөздөрдүн мисалы. Ар бир жарандын кадыр-баркын жана ишкердик аброюн түшүргөн билип туруп жалган маалымат таратуу, жалаа жабуу катары квалификацияланышы мүмкүн, ал юридикалык жоопкерчиликке алып келет. Мындан тышкары, гендердик негизде кемсинтүүлөрдү колдонуу дискриминациядан коргоо жөнүндөгү мыйзамдын жоболоруна туура келиши мүмкүн. 

Сунуштар: Бул учурда кемсинткен маалыматтарды таратуу фактыларын сөзсүз түрдө документтештирүү зарыл. Ал үчүн шилтемелерди, экран сүрөттөрүн (скриншотторду) сактап коюңуз. Мындай учурларда Борбордук шайлоо комиссиясына же укук коргоо органдарына арыз менен кайрылуу керек. Ошондой эле социалдык тармактарда жайгаштырылган кемсинткен постторду же комментарийлерди өчүрүү аракетин көрүү зарыл. Бул үчүн, посттун же комментарийдин оң жагындагы үч чекитти басып, «Колдлонуучуга же постко арыздануу» функциясын колдонуп, социалдык тармактын администрациясына кайрылыңыз.','APPROVED','site',"id",'2024-12-01T06:36:42.092+00:00','2024-11-20T20:29:04.389+00:00','2024-12-01T06:36:42.092+00:00' FROM "violation_types" WHERE "slug"='hate-speech';
