SELECT 'MM-2024-1008',42.21084657560504,75.72017669677736,'naryn','Кочкор району','https://www.facebook.com/groups/497343304021469/permalink/2014459878976463/?rdid=SxcAmatLmsstIDhR&share_url=https%3A%2F%2Fwww.facebook.com%2Fshare%2Fv%2FN9UxKW1aaSqTUSPp%2F#','Фейсбук жана Инстаграмда 11-12 жаштагы баланы диета сактабагандыгы жана бир нече килограммга арыктаганы үчүн урушуп жаткан видео тарап жатат.','Баалоо: Бул видеодо бала үчүн узак мөөнөттүү терс кесепеттерге алып келиши мүмкүн болгон психологиялык зомбулуктун мисалы көрсөтүлөт. Чоңдордун агрессивдүү жүрүм-туруму жана баланын сырткы көрүнүшү тууралуу кемсинткен сөздөр анын өзүн өзү сыйлоо сезимине терс таасир тийгизет, уялуу сезимин күчөтөт жана тамактануунун бузулуусуна же тынчсыздануу же депрессия сыяктуу психикалык саламаттыктын көйгөйлөрүнө алып келиши мүмкүн. 

Сунуштар: Балдар да чоң адамдардай эле сезимдерге ээ, бирок алар бир топ алсыз болушат. Ар бир баланын өзүнүн кадыр-баркы бар, аны чоңдор сөзсүз урматташы керек жана бийлик же тажрыйбадагы артыкчылыктарын кыянаттык менен пайдаланбашы зарыл. Ошондуктан, чоңдор баланын кадыр-баркын жана сезимдерин кемсинтпей, баарлашууда жана үйрөтүүдө конструктивдүү ыкмаларды колдонушу керек.
Мындай мазмундарга колдонуучулар төмөнкүчө реакция кылышы керек:
    1. Мындай видеолорду жайылтууга жана таркатууга жол берилбей тургандыгы тууралуу авторлорго түз кайрылуу.
    2. Ошондой эле, социалдык тармактын модераторлоруна даттануу жөнөтүү.','APPROVED','site',"id",'2024-12-01T06:38:06.813+00:00','2024-11-20T22:21:24.401+00:00','2024-12-01T06:38:06.813+00:00' FROM "violation_types" WHERE "slug"='hate-speech';
