SELECT 'MM-2024-1009',40.56937143958841,72.81738281250001,'osh','Ош','https://www.facebook.com/story.php?story_fbid=551578210652604&id=100074012886096&rdid=fWm54H8q5gM2Wn84','Мессенджерден жана социалдык тармактардан мононатрий глутаматы биз үйдө да, кафелерде да көп өлчөмдө керектеген уу экендигин жана анын ден соолукка олуттуу кесепеттери бар деген билдирүүлөрдү көрдүм.','Баалоо: Мононатрий глутаматы (Е621) ден соолукка олуттуу таасир тийгизе турган уу деген ырастоолор апыртылган жана көпчүлүк учурларда илимий далилдерге туура келбейт. ДСУ (Бүткүл дүйнөлүк саламаттыкты сактоо уюму) жана башка кадыр-барктуу уюмдар мононатрий глутаматты ченеми менен колдонгондо коопсуз деп эсептешет. Мононатрий глутаматы көптөгөн белоктуу азыктарда кездешкен табигый аминокислота жана даам күчөтүүчү катары кеңири колдонулат. 

Сунуш: Маалымат булактарын текшерип, керектүү маалыматты интернеттен ачкыч сөздөрдү колдонуп издеңиз. Ошол эле учурда тамактануу, ден соолук, фармакология жана башка адистештирилген темалар боюнча маалымат булактарына көңүл буруу маанилүү. Ишенимдүү булактарга артыкчылык берүү керек – булар алдыңкы медициналык мекемелердин жана мамлекеттик органдардын расмий сайттары, ошондой эле тармактын абройлуу адистеринин квалификациясы жана илимий даражалары көрсөтүлгөн китептери болушу мүмкүн. Изилдөөгө шилтемелердин жеткиликтүүлүгүн, изилдөө жүргүзүлгөн убакытты жана ыкмаларын, ошондой эле алынган маалыматтардын негизинде чыгарылган корутундуларды эске алуу маанилүү. Илимий негиздери жок үстүртөн айтылган пикирлер, аргументтери жана далилдери жок колдонуучулардын ушундай билдирүүлөрү четке кагылышы керек.','APPROVED','site',"id",'2024-12-01T06:37:33.853+00:00','2024-11-20T22:25:58.364+00:00','2024-12-01T06:37:33.853+00:00' FROM "violation_types" WHERE "slug"='disinformation';
