SELECT 'MM-2024-1014',42.93028505122966,74.61090087890626,'chuy','Бишкек','https://www.instagram.com/p/DCTmrRxsNrT/?img_index=1&igsh=Nm1udThsOGV2OXE3',NULL,'Жогорудагы билдирүүдө Kloop медиасында президенттин кайрылуусу айтылат. Бул билдирүү кастык тил катары кабыл алынса болобу?
Кастык тили, адатта, белгилүү бир топко карата жек көрүү, кемсинтүү же дискриминацияны камтыйт. Президенттин билдирүүсүндө "псевдожурналисттер" жана "псевдоблогерлер" деген терминдер колдонулган. Бул сөздөр журналисттер менен блогерлердин ишмердүүлүгүнө шек келтирип, аларды коомчулуктун алдында дискредитациялоо аракети катары кабылданышы мүмкүн.
Бирок билдирүүдө түздөн-түз жек көрүү, зомбулукка чакыруу же дискриминация жок. Ошондуктан, аны кастык тил деп аныктоо талаштуу. Бул билдирүү көбүнчө сын пикири бар саясий риторика катары бааланат.
Саясий билдирүүлөр жана журналистиканын ролу
Президент Садыр Жапаровдун журналисттер жана блогерлер тууралуу билдирүүсү коомчулукта талкуу жаратты. Анда ал айрым "псевдожурналисттер" жана "псевдоблогерлер" тууралуу айтып, өлкөдө сөз эркиндиги бар экенин белгилеген.
Бул билдирүү ар кандай пикирлерди жаратты. Бир тараптан, бул расмий бийликтин коомчулук менен ачык диалогго даярдыгын көрсөтүшү мүмкүн. Башка тараптан, "псевдожурналист" жана "псевдоблогер" деген терминдердин колдонулушу сынга алынып, сөз эркиндигине басым болуп жаткандай таасир калтырууда.
Сөз эркиндиги жана журналистиканын мааниси
Журналисттердин негизги максаты – коомдук кызыкчылыкты коргоо жана маанилүү маселелер боюнча объективдүү маалымат берүү. Ошондуктан, аларга карата терс мүнөздөмөлөр колдонулушу коомчулуктун маалымат каражаттарына болгон ишенимине доо кетириши мүмкүн.
Медиа менен бийликтин өз ара байланышы
Коомдогу маалымат агымын өнүктүрүү үчүн бийлик менен журналисттердин ортосунда ачык жана конструктивдүү диалог болушу маанилүү. Бул сөз эркиндигин чектебей, тескерисинче, маалымат мейкиндигинин өнүгүшүнө өбөлгө түзөт.
Жыйынтык
Президенттин билдирүүсү медиа тармагындагы кээ бир маселелерге көңүл бурууга түрткү болду. Бирок мындай билдирүүлөр журналисттердин ишмердүүлүгүнө терс таасирин тийгизбеши үчүн, бийлик менен медиа өкүлдөрүнүн ортосунда тең салмактуу байланыш керек.  Билдирүүдөгү "псевдожурналист" жана "псевдоблогер" деген терминдердин колдонулушу кастык тили болуп саналат.','APPROVED','site',"id",'2025-03-25T07:28:57.823+00:00','2024-11-28T06:32:28.241+00:00','2025-03-25T07:28:57.823+00:00' FROM "violation_types" WHERE "slug"='hate-speech';
