SELECT 'MM-2024-1016',42.85985981506279,74.29229736328126,'chuy','Сокулук','https://www.facebook.com/reel/1118451113403460?rdid=6S9yCX0YxM4z9syu&share_url=https%3A%2F%2Fwww.facebook.com%2Fshare%2Fr%2F15NG3bzcKi%2F#','Бул эмне деген чечим? Бишкектин мэриясы кыргызстандыктарды шаарга киргизпейт бекен эми бекер?','Бул маалымат боюнча 2024-жылдын 1-декабрында Фейсбукта КР президентинин басма сөз кызматынын жетекчиси Дайырбек Орунбеков (https://www.facebook.com/daiyrbek.orunbekov) тарабынан маалымат жарыяланды: "Эми Бишкек шаарына башка аймактардан келген унаалар акча төлөп кирет”-деген жалган видео тарап жатат.
Бул эски жана туура эмес маалымат, тактап айтканда жай айында жол тыгынын чечу боюнча альтернатива катара сунуштар тушкон, бирок олко башчысы тарабынан колдоо алган эмес.
Анын ордуна жолдорду кенейтип, унаа токтоочу жайларды куруу тапшырмасын койгон. Кордунуздор, быйыл Бишкектеги негиздер кочолор кенетилип, жаныдан асфальт басылып, капиталдык ондоодон отту.
Андыктан, “башка аймактан келген унаалар үчүн акча төлөтүү каралып жатаптыр”-деген маалыматтарга ишенбеңиздер жана кабар болбонуздар".
Бул постту жарыяланган SOKOL.MEDIA.KG Instagram аккаунтунун администраторлору алардын SMM-кызматкери ката кетиргенин айтып, андан соң жалган маалыматты өчүрүшкөн.
Сунуш: Мындай маалыматты такташ үчүн расмий жана мамлекеттик органдарга кайрылыңыз. Мисалы, бул маалыматтын чын-бышыгын тактоо үчүн Бишкек шаардык мэриясына кайрылсаңыз болот эле.','APPROVED','site',"id",'2024-12-11T05:29:12.873+00:00','2024-12-02T08:32:31.841+00:00','2024-12-11T05:29:12.873+00:00' FROM "violation_types" WHERE "slug"='disinformation';
