SELECT 'MM-2025-1029',42.827638636242284,74.53948974609376,'chuy','Бишкек','https://www.facebook.com/share/v/18RqS9hYuF/','Ушул окуя тууралуу комментарий берип койгулачы, кантип санарип шылуунга кабылды, эмне болгон шылуун эле, эмнеге  бир учурда 2-3 банк бир адамга насыя бере беришет.','2024-жылдын 17-октябрь күнү Бишкек шаарынын Свердлов РИИБге Мээрим Ташыбекова кайрылган, себеби белгисиз адамдар телефон аркылуу өздөрүн Улуттук коопсуздук мамлекеттик комитетинин жана Улуттук банктын кызматкерлерибиз деп тааныштырып жана алдоо жолу менен ишеничине киришип, 825 миң сом акчасын котортуп алгандыгы тууралуу билдирген. Аталган факты боюнча КРнын Кылмыш-жаза кодексинин «Алдамчылык» беренеси боюнча иш козголгон.

Укук коргоо кызматкерлери шектүүнүн өздүгүн тактап, кармоого жетишкен. Ал Бишкек шаардык ички иштер башкы башкармалыгынын убактылуу кармоочу жайына камалган 23 жаштагы А.Х. болуп чыкты. Тергөө иштери уланууда.

Мээрим Ташыбекова мурда журналист болуп иштеп, учурда Кыргызпатенттин басма сөз катчысы кызматын аркалайт. Бул окуя боюнча маалыматты бул шилтеме аркылуу тааныш аласыздар - https://kaktus.media/doc/516891_bishkekchanky_obmanom_zastavili_vziat_kredity_v_neskolkih_bankah_i_obokrali_video.html','APPROVED','site',"id",'2025-04-09T06:50:57.635+00:00','2025-01-29T11:53:06.471+00:00','2025-04-09T06:50:57.635+00:00' FROM "violation_types" WHERE "slug"='digital-fraud';
