SELECT 'MM-2025-1048',39.886162549420646,70.50888061523439,'batken','Баткен району Ак Сай',NULL,NULL,'Социалдык тармактарда Кыргызстандын президентинин жубайы Айгүл Жапарованын, ошондой эле президенттин өзүнүн атынан Садыр Жапаровдун атынан фейк баракчалар жана билдирүүлөр түзүлүүдө. Алдамчылар колдонуучуларды алдоо үчүн ар кандай айла-амалдарды колдонушат: алар өздөрүнүн атынан мамлекеттик кызматка кирүүгө убада беришет, акчалай сыйлыктар жана кредиттерди төлөө үчүн каржылык жардам бөлүштүрүлөөрүн жарыялашат.
Алдамчылар белгилүү саясатчылардын, коомдук ишмерлердин жана таасирдүү адамдардын сүрөттөрүн жана видеолорун ошол адамдарга ишенген жана алардын “кеңештерин” жана “сунуштарын” аткарууга даяр колдонуучуларды адаштыруу үчүн колдонушат. Акыркы убакта шылуундар мамлекеттик органдардын, банк мекемелеринин, уюлдук операторлордун, атүгүл укук коргоо органдарынын – ИИМдин, УКМКнын формаларын активдүү түрдө жасап, өздөрүнүн жасалма веб-сайттарын түзүп, кол тамгасы жана мөөрлөрү бар жасалма бланктарга каттарды жөнөтүп жатышат. Мындай билдирүүлөргө эч качан кылдат текшерүүсүз жооп бербеңиз – мамлекеттик органга, мекемеге, компанияга телефон чалып, кандайдыр бир чара көрүүнүн алдында маалыматты текшериңиз.
Эсиңизде болсун, биринчи кезекте шылуундар сиздин эмоцияларыңызга (коркуу, жакындарыңыз үчүн коркуу, боор ооруу) жана сыйлыктарды же акчаны оңой алуу каалооңузга таасир этет. Эч качан шектүү маалымат булактарына ишенбеңиз - мындай жарыялардын кайдан келгенине көңүл буруңуз, расмий органдар тарабынан берилген төгүндөөлөрдү текшериңиз. Мындай жарнамаларды укук коргоо органдарына билдирип, кылмыштуулукту токтотуу жана башка колдонуучуларга эскертүү берүүңүздөрдү суранабыз.','APPROVED','site',"id",'2025-03-17T06:22:21.940+00:00','2025-03-13T05:19:30.348+00:00','2025-03-17T06:22:21.940+00:00' FROM "violation_types" WHERE "slug"='digital-fraud';
