SELECT 'MM-2025-1050',40.066248922057945,70.81940389739657,'batken','Баткен шаары',NULL,'Менин досум жакынкы күндөрү бир досунун атынан алдамчылык менен  жазуунун себебинен 22 мин сом акчасын мбанк аркылуу которуу жолу менен алданып калды','Учурда шылуундар көбүнчө тааныштардын атын колдонуу менен, "тез акча керек", "телефон өчүп калды", "карта блоктолду" деген сыяктуу жалган себептер менен адамдарды алдап акча алышат.  

 Эмне кылса болот?  
1. Банкка кайрылыңыз – операцияны токтотууга аракет кылуу үчүн (эгер убакыт өтүп ктепесе).  
2. Милицияга билдириңиз – картанын транзакциялык тарыхы менен (шылуундарды издеп табуу мүмкүн).  
3. Досторго эскертүү жибериңиз – алар да мошенниктердин колуна түшүшү мүмкүн.  

 Келечектө эмнеге көңүл буруу керек?  
- Тааныштардан келген "төлөм" сураган каттарга скептикалык мамиле кылуу.  
- Текшерүүсүз акча жөнөтпөө – алдын ала телефон аркылуу ырастоо!  
- MBank же башка тиркемелерде каттоодо эки кадамдуу аутентификация зарыл.','APPROVED','site',"id",'2025-04-09T08:09:21.597+00:00','2025-03-13T05:26:06.692+00:00','2025-04-09T08:09:21.597+00:00' FROM "violation_types" WHERE "slug"='digital-fraud';

