SELECT 'MM-2025-1052',39.8928799002948,71.30049201150543,'batken','Баткен','https://fb.me/6fBwZCdad',NULL,'Бул маалымат белгисиз баракчада жарыяланган - ээси ким экен жазылган жок, азыркы учурда баракчада маалыматтар өчүрүлгөн. https://www.facebook.com/story.php?story_fbid=647766601070821&id=576406052218245','APPROVED','site',"id",'2025-04-09T07:18:27.905+00:00','2025-03-13T05:27:26.939+00:00','2025-04-09T07:18:27.905+00:00' FROM "violation_types" WHERE "slug"='disinformation';

