SELECT 'MM-2025-1054',43.094966325413395,74.53674316406251,'chuy','Виноградное',NULL,'Ушул маалымат чынбы же жалганбы?','Бул маалымат чын, жалган эмес, расмий ММКда жарыяланган.','APPROVED','site',"id",'2025-04-09T06:59:21.270+00:00','2025-03-13T05:33:13.645+00:00','2025-04-09T06:59:21.270+00:00' FROM "violation_types" WHERE "slug"='digital-fraud';
