SELECT 'MM-2025-1095',40.530142974124026,72.79322147369386,'osh','Ош','https://www.facebook.com/share/v/12GRFgsnsNq/','Чыгып кеткиле деген комент жазгандар, бул эмне дегени, кастыкпы? Биз да кыргызстандык жарандарбыз, укук бузулса унчукпай отуралыкпы?','Сиздин окуяңыз тил жана билдирүүлөр жөнүндө маанилүү суроолорду көтөрөт, алар душмандык катары кабыл алынышы мүмкүн. "Чыгып кеткиле", "дарбаза ачык" деген фразалар белгилүү бир жарандык топтун укуктарынан ажыратуу, алардын маанилүү маселелер боюнча өз пикирлерин билдирүү укугунан ажыратуу чакырыгы катары кабыл алынышы мүмкүн. Эгерде бул белгилүү бир этникалык же социалдык топко карата айтылса, бул жек көрүүнүн же дискриминациянын белгиси катары бааланышы мүмкүн.

Тилди колдонуу күчкө ээ экенин унутпоо маанилүү, жана кээ бир билдирүүлөр топтор ортосундагы чыңалууну күчөтүшү мүмкүн. Укуктар бузулганда үнсүз калууга чакыруулар да маселелерди көз жаздымда калтыруу катары түшүндүрүлүшү мүмкүн, бул жагдайдын дагы начарлашына алып келиши мүмкүн.

Жалпысынан, мындай билдирүүлөр терең талдоону жана талкууну талап кылат, жек көрүүнү козутпоо жана жарандар арасында өз ара түшүнүшүүнү бекемдөө үчүн.','APPROVED','site',"id",'2025-07-27T08:33:23.139+00:00','2025-04-15T07:26:35.968+00:00','2025-07-27T08:33:23.139+00:00' FROM "violation_types" WHERE "slug"='hate-speech';
