SELECT 'MM-2025-1097',42.50754004948742,72.30445861816408,'talas','Талас','https://www.facebook.com/share/v/1FBRrUzTNJ/','Бул киши өзбек мигрантты как собаку держу дейт...Адамды да ушундай сөз менен айтабы?','Бул билдирүүдө адамды жаныбарга салыштырып, унижать кылган сөздөр колдонулуп жатат. Мындай сөздөр катаал жана жек көрүүчү тилди чагылдырат, анткени алар адамдарды алардын улутуна, этникалык таанымына же социалдык статусуна карап бөлүп көрсөтөт. 

Адамды "ит, собака" катары сүрөттөө, анын аброюна жана адамдык укуктарына каршы келет. Мындай сөздөр коомдогу бөлүнүүлөрдү, жек көрүүнү жана дискриминацияны күчөтөт. Ошондуктан, мындай тилди колдонуу туура эмес жана аны жоюу үчүн аракет кылуу керек. Адамдарды сыйлоо жана алардын укуктарын урматтоо — бардык коомдор үчүн маанилүү принциптер. 

Модераторлор бул мазмунду алып салышы үчүн жана ал мындан ары таралбашы үчүн, сиз мындай материалдарды социалдык платформанын колдоо кызматына билдирсеңиз болот.','APPROVED','site',"id",'2025-07-27T08:48:55.577+00:00','2025-04-16T09:10:25.775+00:00','2025-07-27T08:48:55.577+00:00' FROM "violation_types" WHERE "slug"='hate-speech';
