SELECT 'MM-2025-1100',41.49057783237735,71.75445556640626,'jalal-abad','Кербен','https://www.facebook.com/share/v/1CDdeQbM7D/','Көп ушундай реклама журуп атат','Бул видео дагы алдамчылык максатында түзүлгөн фейк жарнама. Анда Кыргыз Республикасынын Президенти Садыр Жапаровдун жүзү жана үнү колдонулган. Бул видео жасалма интеллекттин жардамы менен түзүлгөн, жана реалдуу видео эмес.
Видео  Cbb953 аттуу социалдык тармактагы шектүү баракча аркылуу жарыяланган. Аталган баракчанын өзү да ишенимсиз көрүнөт жана негизинен шектүү мазмундагы контенттерди жарыялап турат.
Бул жарнама финансылык пайда табуу максатында колдонулуп, элди ишендирүү үчүн өлкө башчысынын жүзү жасалма түрдө колдонулган. Президенттин расмий баракчаларында мындай билдирүү жок, жана видеодо айтылган компания тууралуу эч бир расмий сайттан же мамлекеттик органдардан маалымат табылган эмес.
Президенттин сүйлөп жаткан видеосу жасалма;


Видеодо көрсөтүлгөн финансылык долбоор тууралуу расмий булактарда эч кандай маалымат жок;


Бул видео социалдык тармактагы шектүү аккаунттар аркылуу тараган.


Жыйынтык:
Бул видео — элди алдоо жана ишенимине кирүү үчүн жасалма интеллект менен жасалган фейк жарнама. Андай видеолорго ишенбөөгө чакырабыз. Финансылык сунуштарга макул болуудан мурун ар дайым расмий булактарды текшериңиз. Шектүү материалдар тууралуу социалдык тармактардын администрациясына билдирип коюу маанилүү.','APPROVED','site',"id",'2025-07-25T15:52:50.489+00:00','2025-04-18T09:26:39.362+00:00','2025-07-25T15:52:50.489+00:00' FROM "violation_types" WHERE "slug"='digital-fraud';
