SELECT 'MM-2025-1109',42.76314586689494,73.85559082031251,'chuy','Кара Балта','https://www.facebook.com/share/v/1FsGkhzPmi/','ЖИ менен жасалган видео, алдамчылыктын түрү','Бул видео — алдамчылардын жасалма жарнамасы. Анда Кыргыз Республикасынын Жогорку Кеңешинин депутаты Дастан Бекешовдун жүзү колдонулган. Анын сүйлөп жаткан видеосу жасалма интеллекттин жардамы менен түзүлгөн.
Бул фейк-видео “Islamic Portal” деп аталган Facebook баракчасы аркылуу жарыяланган. Ал баракча көбүнчө исламга байланыштуу маалыматтарды бөлүшөт, бирок бул жолу шектүү компанияны жарнамалаган жасалма контентти тараткан.
Видеодо айтылган компания тууралуу эч бир расмий сайтта маалымат жок;


Дастан Бекешовдун расмий социалдык баракчаларында мындай билдирүү же кызмат тууралуу эч кандай маалымат жарыяланган эмес.


Жыйынтык:
Бул видео — алдамчылык максатында жасалган фейк жарнама. Жарандарды мындай видеолорго ишенбөөгө жана расмий булактардан так маалымат алууга чакырабыз. Мындай шектүү видеолорду социалдык тармактын администрациясына билдирип коюу зарыл.','APPROVED','site',"id",'2025-06-30T09:40:34.424+00:00','2025-05-14T17:34:39.988+00:00','2025-06-30T09:40:34.424+00:00' FROM "violation_types" WHERE "slug"='digital-fraud';
