SELECT 'MM-2025-1113',40.538851525354666,72.82150268554689,'osh','Ош','https://www.instagram.com/reel/DKwVKeaMp5T/?igsh=YzljYTk1ODg3Zg==','Ушундай суроо да болобу? Эмнеге оштуктарга ушундай мамиле - Ошто башка кыргыздао жашайбы?','Журналисттердин суроосу кыздардын тегине басым жасалгандыктан бир жактуу деп кабыл алынышы мүмкүн. Суроо Кыргызстандын кайсы бир аймагы – Ош облусу жана бул аймактан келген кыздар тууралуу стереотиптерге байланыштуу болушу мүмкүн. Бул жек көрүү катары кабыл алынышы мүмкүн.

Мындай суроолор адамдарда ар кандай реакцияларды жаратып, маданий жана этникалык жек көрүүчүлүккө байланыштуу сезимтал темаларды козгошу мүмкүн экенин эске алуу зарыл. Ошондуктан журналисттер керексиз чыр-чатактарды жаратпоо, терс стереотиптерди, жек көрүүлөрдү камтыбоо, коомду бөлүп-жаруу практикасына салым кошпоосу үчүн суроолорду түзүшү керек.','APPROVED','site',"id",'2025-07-27T08:43:22.721+00:00','2025-06-12T06:01:21.646+00:00','2025-07-27T08:43:22.721+00:00' FROM "violation_types" WHERE "slug"='hate-speech';
